\\e90e\";\n}\n.icon-phone:before {\n  content: \"\\e90a\";\n}\n.icon-mail:before {\n  content: \"\\e90b\";\n}\n.icon-prev:before {\n  content: \"\\e900\";\n}\n.icon-arrow-down:before {\n  content: \"\\e901\";\n}\n.icon-next:before {\n  content: \"\\e902\";\n}\n.icon-arrow-left:before {\n  content: \"\\e903\";\n}\n.icon-arrow-right:before {\n  content: \"\\e904\";\n}\n.icon-check:before {\n  content: \"\\e905\";\n}\n.icon-search:before {\n  content: \"\\e906\";\n}\n.icon-timer:before {\n  content: \"\\e907\";\n}\n.icon-tringle:before {\n  content: \"\\e908\";\n}\n.icon-user:before {\n  content: \"\\e909\";\n}\n","@font-face {\n  font-style: normal;\n  font-weight: 700;\n  font-family: \"Gilroy\";\n  font-display: swap;\n  src: url(\"../fonts/Gilroy-Semibold.woff2\") format(\"woff2\"), url(\"../fonts/Gilroy-Semibold.woff\") format(\"woff\");\n}\n@font-face {\n  font-style: normal;\n  font-weight: 400;\n  font-family: \"Gilroy\";\n  font-display: swap;\n  src: url(\"../fonts/Gilroy-Regular.woff2\") format(\"woff2\"), url(\"../fonts/Gilroy-Regular.woff\") format(\"woff\");\n}\n@font-face {\n  font-style: normal;\n  font-weight: 700;\n  font-family: \"Gilroy-Medium\";\n  font-display: swap;\n  src: url(\"../fonts/Gilroy-Medium.woff2\") format(\"woff2\"), url(\"../fonts/Gilroy-Medium.woff\") format(\"woff\");\n}\n@font-face {\n  font-style: normal;\n  font-weight: 700;\n  font-family: \"Poppins\";\n  font-display: swap;\n  src: url(\"../fonts/Poppins-Regular.woff2\") format(\"woff2\"), url(\"../fonts/Poppins-Regular.woff\") format(\"woff\");\n}\n@font-face {\n  font-style: normal;\n  font-weight: 700;\n  font-family: \"Poppins\";\n  font-display: swap;\n  src: url(\"../fonts/Poppins-SemiBold.woff2\") format(\"woff2\"), url(\"../fonts/Poppins-SemiBold.woff\") format(\"woff\");\n}\n@font-face {\n  font-style: normal;\n  font-weight: 700;\n  font-family: \"TT-Firs\";\n  font-display: swap;\n  src: url(\"../fonts/TT_Firs_Neue_Trial_DemiBold.woff2\") format(\"woff2\"), url(\"../fonts/TT_Firs_Neue_Trial_DemiBold.woff\") format(\"woff\");\n}\n@font-face {\n  font-style: normal;\n  font-weight: 700;\n  font-family: \"TT-Firs\";\n  font-display: swap;\n  src: url(\"../fonts/TT_Firs_Neue_Trial_ExtraBold.woff2\") format(\"woff2\"), url(\"../fonts/TT_Firs_Neue_Trial_ExtraBold.woff\") format(\"woff\");\n}\n[class^=icon-], [class*=\" icon-\"] {\n  /* use !important to prevent issues with browser extensions that change fonts */\n  font-family: \"icomoon\" !important;\n  speak: never;\n  font-style: normal;\n  font-weight: normal;\n  font-variant: normal;\n  text-transform: none;\n  line-height: 1;\n  /* Better Font Rendering =========== */\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n.icon-calendar:before {\n  content: \"\\e90c\";\n}\n\n.icon-close:before {\n  content: \"\\e90d\";\n}\n\n.icon-arrow-reverse:before {\n  content: \"\\e90e\";\n}\n\n.icon-phone:before {\n  content: \"\\e90a\";\n}\n\n.icon-mail:before {\n  content: \"\\e90b\";\n}\n\n.icon-prev:before {\n  content: \"\\e900\";\n}\n\n.icon-arrow-down:before {\n  content: \"\\e901\";\n}\n\n.icon-next:before {\n  content: \"\\e902\";\n}\n\n.icon-arrow-left:before {\n  content: \"\\e903\";\n}\n\n.icon-arrow-right:before {\n  content: \"\\e904\";\n}\n\n.icon-check:before {\n  content: \"\\e905\";\n}\n\n.icon-search:before {\n  content: \"\\e906\";\n}\n\n.icon-timer:before {\n  content: \"\\e907\";\n}\n\n.icon-tringle:before {\n  content: \"\\e908\";\n}\n\n.icon-user:before {\n  content: \"\\e909\";\n}\n\n/* stylelint-disable */\n:root {\n  --frame-width: 1920;\n  --rem-function: 16px;\n  --error-bg: #f00;\n  --body-bg:#fefefe;\n  --body-font-size: 16px;\n  --content-width: 1440px;\n  --content-width-mode: 1920px;\n  --container-offset: clamp(16px, 2.7778vw, 40px);\n  --container-width: calc(var(--content-width) + (var(--container-offset) * 2));\n  --container-width-mode: calc(var(--content-width-mode) + (var(--container-offset) * 2));\n  --default-paddi