//         @include  small-tablet{\n//           font-size: 80px;\n//         }\n//       }\n\n//       &__text{\n//         text-align: center;\n//         font-size: 24px;\n//       }\n//     }\n//   }\n\n//   &__value {\n//     color: var(--cl-k);\n//     text-align: center;\n//     font-family: var(--font-family);\n//     font-size: clamp(40px, 7.018vw, 80px);\n//     font-style: normal;\n//     font-weight: 600;\n//     line-height: 100%;\n//   }\n\n//   &__text {\n//     color: var(--cl-h);\n//     text-align: start;\n//     font-size: clamp(16px, 3.158vw, 36px);\n//     font-family: var(--font-family);\n//     font-style: normal;\n//     font-weight: 400;\n//     line-height: normal;\n//     text-transform: capitalize;\n//   }\n// }\n\n// .caption {\n//   position: absolute;\n//   padding: 20px 24px;\n//   border-radius: 24px;\n//   background: var(--bg-l);\n//   left: 8px;\n//   right: 8px;\n//   bottom: 8px;\n//   z-index: 20;\n\n//   color: var(--cl-m);\n//   font-family: var(--font-family);\n//   font-size: 16px;\n//   font-style: normal;\n//   font-weight: 500;\n//   line-height: normal;\n//   display: grid;\n//   grid-template-columns: repeat(auto-fill, minmax(200px, 200px));\n// }\n\n.editor {\n  display: flex;\n  flex-direction: column;\n  gap: clamp(16px, 1.6667vw, 24px);\n  position: relative;\n\n  @include mobile {\n    @include headers {\n      text-align: center;\n    }\n  }\n\n  .wpcf7 {\n    width: 100%;\n\n    @include for-small-tablet {\n      max-width: 580px;\n      margin-top: 20px;\n    }\n\n    @include small-tablet {\n      max-width: 576px;\n      margin: 0 auto;\n    }\n  }\n\n  p:has(iframe) {\n    height: 100%;\n  }\n\n  // .accent-label {\n  //   @include mobile {\n  //     margin: 0 auto;\n  //   }\n  // }\n\n  iframe {\n    height: 100%;\n    border-radius: 24px;\n    aspect-ratio: 1 / 1;\n    max-width: 100%;\n    width: 100%;\n    min-height: 500px;\n  }\n\n  // .caption {\n  //   position: absolute;\n  //   padding: 20px 24px;\n  //   border-radius: 24px;\n  //   background: var(--Main-Neutral-100, #f8f8f8);\n  //   left: 8px;\n  //   right: 8px;\n  //   bottom: 8px;\n  // }\n\n  // .main-button {\n  //   margin-top: 20px;\n  // }\n\n  p:not([class]) {\n    font-family: var(--font-family);\n    font-weight: 500;\n    font-size: clamp(18px, 1.3889vw, 20px);\n    line-height: 145%;\n    text-align: center;\n    color: var(--neutral-700);\n  }\n\n  ul:not([class]) {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n\n    li {\n      color: var(--cl-i);\n      font-family: var(--second-family);\n      font-size: clamp(12px, 0.972vw, 14px);\n      font-style: normal;\n      font-weight: 400;\n      line-height: 150%;\n      position: relative;\n      padding-left: 20px;\n\n      &:before {\n        content: \"\";\n        position: absolute;\n        width: 3px;\n        height: 3px;\n        border-radius: 50%;\n        pointer-events: none;\n        left: 10px;\n        top: 8.5px;\n        background: var(--cl-i);\n      }\n    }\n  }\n\n  ol:not([class]) {\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    counter-reset: li;\n    margin-bottom: clamp(8px, 1.5625vw, 16px);\n\n    li {\n      color: var(--cl-j);\n      font-family: var(--font-family);\n      font-size: 16px;\n      font-style: normal;\n      font-weight: 500;\n      line-height: normal;\n      position: relative;\n      padding-left: 20px;\n      counter-increment: li;\n\n      &:before {\n        content: counter(li) \".\";\n        position: absolute;\n        top: 0;\n        left: 3px;\n        color: var(--cl-j);\n        font-family: var(--font-family);\n        font-size: 16px;\n        font-style: normal;\n        font-weight: 500;\n        line-height: normal;\n        display: inline-block;\n      }\n    }\n  }\n\n  // &s {\n  //   display: grid;\n  //   grid-template-columns: 1.2fr 1fr;\n  //   grid-gap: clamp(35px, 8.4746vw, 117px);\n\n  //   &__coll {\n  //     &:only-of-type {\n  //       grid-column: 1/-1;\n  //     }\n  //   }\n  // }\n\n  table:not([class]) {\n    border-radius: 24px;\n    border: 1px solid var(--bg-d);\n    border-collapse: initial !important;\n\n    tr:first-child {\n      overflow: hidden;\n      width: 100%;\n\n      td {\n        color: var(--cl-m);\n        background: var(--bg-l);\n\n        &:first-of-type {\n          border-radius: 24px 0 0 0;\n        }\n\n        &:last-of-type {\n          border-radius: 0 24px 0 0;\n        }\n      }\n    }\n\n    tr {\n      td {\n        border-bottom: solid 1px var(--bg-d);\n      }\n\n      &:last-child {\n        td {\n          border: none !important;\n        }\n      }\n    }\n\n    td {\n      padding: 16px 0;\n      color: var(--cl-j);\n      font-family: var(--font-family);\n      font-size: 16px;\n      font-style: normal;\n      font-weight: 400;\n      line-height: normal;\n    }\n  }\n\n  .row {\n    display: inline-flex;\n    flex-wrap: wrap;\n    justify-content: center;\n    gap: 24px;\n\n    &:has(.main-button:only-child) {\n      display: initial;\n    }\n\n    .main-button {\n      @include mobile {\n        flex-grow: 1;\n      }\n    }\n  }\n\n  blockquote {\n    display: flex;\n    flex-direction: column;\n    gap: 8px;\n    max-width: 450px;\n    margin: 0 auto;\n    border-radius: 2px;\n    padding-left: 18px;\n    border-left: solid 2px #c4ee50;\n\n    p:not([class]) {\n      color: var(--cl-j);\n      font-family: var(--font-family);\n      font-size: clamp(12px, 1.5625vw, 16px);\n      font-style: normal;\n      font-weight: 400;\n      line-height: normal;\n\n      &:last-of-type {\n        @include mobile {\n          max-width: 200px;\n          margin-left: auto;\n        }\n      }\n    }\n\n    span {\n      font-family: var(--font-family);\n      font-size: clamp(18px, 2.3438vw, 24px);\n      font-style: normal;\n      font-weight: 500;\n      line-height: normal;\n      text-transform: capitalize;\n\n      @include mobile {\n        font-family: var(--second-family);\n      }\n    }\n\n    @include mobile {\n      margin-left: 16px;\n    }\n  }\n}\n\n.slider-controls {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: var(--gap);\n\n  .slider-btn {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    width: clamp(44px, 3.75vw, 54px);\n    background: var(--main-yellow);\n    transition: all 0.3s;\n    height: clamp(44px, 3.75vw, 54px);\n\n    &:disabled {\n      background: var(--neutral-200);\n      pointer-events: none;\n    }\n\n    .sprite {\n      width: 16px;\n      height: auto;\n\n      svg {\n        width: 100%;\n        height: auto;\n      }\n    }\n\n    &.next {\n      .sprite {\n        transform: scaleX(-1);\n      }\n    }\n\n    &:hover {\n      background: darken(#fcc833, 10%);\n    }\n  }\n}\n\n.slider-pagination {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  margin-top: 36px;\n  gap: 10px;\n\n  .swiper-pagination-bullet {\n    width: 16px;\n    height: 16px;\n    background: var(--neutral-200);\n    display: flex;\n    opacity: 1;\n    transition: all 0.3s;\n    &-active {\n      background: var(--neutral-600);\n    }\n\n    &:hover {\n      opacity: 0.7;\n    }\n  }\n}\n\n.logo {\n  width: clamp(97px, 12.1528vw, 175px);\n  max-height: 36px;\n  height: auto;\n  display: flex;\n  img,\n  svg {\n    width: 100%;\n    height: auto;\n  }\n}\n","/* stylelint-disable */\n\n@mixin hover {\n  @media (hover: hover) {\n    &:hover {\n      @content;\n    }\n  }\n\n  @media (hover: none) {\n    &:active {\n      @content;\n    }\n  }\n}\n","@use \"../mixins/breakpoint\" as *;\n@use \"../mixins/disable-mob-hover\" as *;\n\n.main-button {\n  max-width: 400px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  transition: all 0.3s;\n  border: 2px solid var(--main-yellow);\n  padding: 16px 64px;\n  height: 59px;\n  font-family: var(--font-family);\n  font-weight: 500;\n  font-size: 18px;\n  line-height: 150%;\n  text-align: center;\n  background: var(--main-yellow);\n  width: fit-content;\n  color: var(--neutral-700);\n\n  @include hover {\n    background: darken(#fcc833, 10%);\n    box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n  }\n\n  &--transparent {\n    color: var(--main-yellow);\n    background: transparent;\n\n    @include hover {\n      background: var(--main-yellow);\n      color: var(--neutral-700);\n      box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n    }\n  }\n\n  &--white {\n    color: var(--neutral-100);\n    border-color: var(--neutral-100);\n    background: transparent;\n\n    @include hover {\n      background: var(--main-yellow);\n      border-color: var(--main-yellow);\n      color: var(--neutral-700);\n      box-shadow: 0 8px 16px rgba(252, 200, 51, 0.3);\n    }\n  }\n}\n\n.telegram-btn {\n  max-width: var(--btn-size);\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: var(--cl-e);\n  border-radius: 8px;\n  aspect-ratio: 1;\n  transition: all 0.3s;\n\n  @include hover {\n    background-color: var(--cl-j);\n  }\n\n  svg {\n    max-width: 90%;\n    width: 100%;\n    height: auto;\n  }\n}\n\n.whatsapp-btn {\n  max-width: var(--btn-size);\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background-color: var(--cl-d);\n  border-radius: 8px;\n  aspect-ratio: 1;\n  transition: all 0.3s;\n\n  @include hover {\n    background-color: var(--cl-i);\n  }\n\n  svg {\n    max-width: 90%;\n    width: 100%;\n    height: auto;\n  }\n}\n"]}
